CREATE TABLE exercise_entries(
   user_id                     VARCHAR(5) NOT NULL PRIMARY KEY
  ,age                         INTEGER  NOT NULL
  ,gender                      VARCHAR(6) NOT NULL
  ,height_m                    VARCHAR(18) NOT NULL
  ,weight_kg                   VARCHAR(17) NOT NULL
  ,experience_level            VARCHAR(12) NOT NULL
  ,workout_frequency_days_week INTEGER  NOT NULL
  ,fat_percentage              VARCHAR(18) NOT NULL
);
